#include <type_traits>

struct S {};
static_assert(!std::has_virtual_destructor_v<S>);

struct B {
    virtual ~B() {}
};
static_assert(std::has_virtual_destructor_v<B>);

struct D : B {
    ~D() {}
};
static_assert(std::has_virtual_destructor_v<D>);

int main() {
    B *pd = new D;
    delete pd;
}
